/// <summary>
/// Bug 286663: CB705- Vendor deals are not filtering based on the header vendor account
/// </summary>
[ExtensionOf(classStr(TAMRebateQueryBuilder))]
final class METTAMRebateQueryBuilder_Extension
{
    private RecId journalRecId;
    private RecId lineRecId;

    // Variable to identify if provision or rebate
    private TAMRebateTransactionType metRebateTransactionType;


}

Method.Source:
/// <summary>
/// Parm method for the rebate transaction type
/// </summary>
/// <param name = "_metRebateTransactionType"><c>TAMRebateTransactionType</c></param>
/// <returns><c>TAMRebateTransactionType</c></returns>
public TAMRebateTransactionType metParmRebateTransactionType(TAMRebateTransactionType _metRebateTransactionType = metRebateTransactionType)
{
    metRebateTransactionType = _metRebateTransactionType;
    return metRebateTransactionType;
}

/// <summary>
/// Filter transactions by the deal custom vendor account
/// Adding the vendor account range
/// </summary>
void metAddVendAccountRange()
{
    // When using line attributes for vendor rebates AccountCode will be set to All
    if (rebateTable.ModuleInventCustVend == ModuleInventCustVend::Vend
    &&  rebateTable.AccountCode          == TableGroupAll::All)
    {
        VendAccount vendAccount = rebateTable.TAMRebateDeal().METVendAccount;

        if (vendAccount)
        {
            // Force the filtering, we are only using line attributes (products) and not header attributes (vendor)
            SysQuery::findOrCreateRange(query.dataSourceTable(this.journalTable()), this.accountJourTableFieldId()).value(vendAccount);
        }
    }
}

/// <summary>
/// Adding the range for the external sales data processed flags based on the transaction types
/// </summary>
void metAddExternalSalesDataRange()
{
    if (metRebateTransactionType == TAMRebateTransactionType::Provision)
    {
        query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, ProvisionProcessed)).value(queryValue(NoYes::No));
    }
    else if (metRebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, RebateProcessed)).value(queryValue(NoYes::No));
    }
}

/// <summary>
/// Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
/// Adding the item distribution method filters
/// Ideally this should only be added in TAMRebateQueryBuilderSalesOrder, TAMRebateQueryBuilderSalesDeliveryNote and TAMRebateQueryBuilderSalesInvoice
/// but TAMRebateQueryBuilderSalesDeliveryNote and TAMRebateQueryBuilderSalesInvoice are internal
/// </summary>
/// <returns>Updated <c>Query</c> object</returns>
public Query buildCalculateAmountQuery()
{
    query = next buildCalculateAmountQuery();

    // Add the item distribution method filter
    this.metAddItemDistributionMethodRange();

    if(query.dataSourceTable(this.journalTable()) && query.dataSourceTable(this.journalTable()).findRange(fieldNum(Common, RecId)))
    {
        journalRecId = any2Int64(query.dataSourceTable(this.journalTable()).findRange(fieldNum(Common, RecId)).value());
    }
    if(query.dataSourceTable(this.transTable()) && query.dataSourceTable(this.transTable()).findRange(fieldNum(Common, RecId)))
    {
        lineRecId = any2Int64(query.dataSourceTable(this.transTable()).findRange(fieldNum(Common, RecId)).value());
    }

    TAMRebateDeal rebateDeal = rebateTable.TAMRebateDeal();

    // Bug 306156: [MS] CB201 - Customer rebates: Attribute Filtering Logic Not Correct - MS SR # 2410100030001214
    if (GUPGlobalEnableFeatureHelper::isPricingRuleHashFeatureEnabled()
    &&  rebateTable.RebateAgreementType
    // When set to True- the custom OR filter logic should apply only for customer rebates.
    && TAMRebateParameters::find().METUseOrAttributes
    // Only for customer rebates
    && rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Cust
    // Customer rebates only with Rebate type standard
    && rebateDeal.RebateTypeGUP == TAMRebateTypeGUP::Standard
    // and rebate output Financial
    && rebateDeal.RebateOutputType == TAMRebateOutputType::Financial)
    {
        GUPPricingRule headerRule, lineRule;
        GUPPricingRuleCondition ruleCondition;
        GUPPricingAttributeLink attributeLink;

        boolean queryRangesAdded = false;            

        // Only check those rules which have OR conditions here.
        // For those rules without OR conditions, the original query building logic can handle them.
        select firstonly RecId from headerRule
            where headerRule.RecId == rebateTable.PricingRuleHeader
               && headerRule.PriceAttributeGroupName != ''
            exists join ruleCondition
            where ruleCondition.RuleId == headerRule.RecId
               && ruleCondition.METisOR == NoYes::Yes;

        // Build query ranges for header rule with OR conditions
        if (headerRule.RecId)
        {
            QueryBuildDataSource qbds = query.dataSourceTable(this.journalTable());
            QueryBuildDataSource qbdsCustTable = query.dataSourceTable(tableNum(CustTable));
            str andQueryRanges, orQueryRanges;
            boolean isOrConditionSetToALL = false;
            FieldId accountFieldId = this.accountJourTableFieldId();

            QueryBuildDataSource metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup, metqbdsGUPEcoResInstanceAttributeValuesBannerGroup;
            QueryBuildDataSource metqbdsCustomerInstanceValue;

            // Second attributes other than 'Customer super group' and 'Banner group'
            while select ruleCondition
                where ruleCondition.RuleId == headerRule.RecId
                join AttributeName, TypeName, RecId, PriceAttributeClassId, Source, AttributeProviderClassId, SourceName, FieldName, AttributeDataType from attributeLink
                where attributeLink.RecId == ruleCondition.ConditionAttribute
                && ruleCondition.conditionValue
            {
                str qbdsName = qbds.name();

                // If there are muliple complex attribute, you have to join all datasource here to build the query range correctly.
                // In this example, I only handle SalesTable and CustTable as attribute source for header rule.
                if (attributeLink.SourceName == METConstants::SalesTable)
                {
                    qbdsName = qbds.name();
                }
                else if (attributeLink.SourceName == METConstants::CustTable)
                {
                    if (!qbdsCustTable)
                    {
                        qbdsCustTable = qbds.addDataSource(tableNum(CustTable));
                        qbdsCustTable.addLink(accountFieldId, fieldNum(CustTable, AccountNum));
                        qbdsCustTable.addSelectionField(fieldNum(CustTable, AccountNum));
                        qbdsCustTable.relations(false);
                        qbdsCustTable.joinMode(JoinMode::InnerJoin);
                        qbdsCustTable.fetchMode(QueryFetchMode::One2One);
                    }

                    qbdsName = qbdsCustTable.name();
                }
                else if (attributeLink.SourceName == METConstants::GUPPricingAttributeProviderCustomerAttribute)
                {
                    if (!metqbdsCustomerInstanceValue)
                    {
                        metqbdsCustomerInstanceValue = qbds.addDataSource(tableNum(CustomerInstanceValue));
                        metqbdsCustomerInstanceValue.addLink(accountFieldId, fieldNum(CustomerInstanceValue, AccountNum));

                        int fieldDataAreaId;

                        // TAMRebateQueryBuilderSalesDeliveryNote and TAMRebateQueryBuilderSalesInvoice are internal :/
                        if (rebateTable.SourceType == TAMRebateSourceType::Ordered)
                        {
                            fieldDataAreaId = fieldNum(SalesTable, DataAreaId);
                        }
                        else if (rebateTable.SourceType == TAMRebateSourceType::Delivery)
                        {
                            fieldDataAreaId = fieldNum(CustPackingSlipJour, DataAreaId);
                        }
                        else
                        {
                            fieldDataAreaId = fieldNum(CustInvoiceJour, DataAreaId);
                        }

                        metqbdsCustomerInstanceValue.addLink(fieldDataAreaId, fieldNum(CustomerInstanceValue, CustomerDataAreaId));
                        metqbdsCustomerInstanceValue.addSelectionField(fieldNum(CustomerInstanceValue, RecId));
                        metqbdsCustomerInstanceValue.relations(false);
                        metqbdsCustomerInstanceValue.joinMode(JoinMode::InnerJoin);
                        metqbdsCustomerInstanceValue.fetchMode(QueryFetchMode::One2One);
                    }

                    if (attributeLink.AttributeName == METConstants::CustomerSuperGroup
                    && !metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup)
                    {
                        metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup = metqbdsCustomerInstanceValue.addDataSource(tableNum(GUPEcoResInstanceAttributeValuesView));
                        metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.addLink(fieldNum(CustomerInstanceValue, RecId), fieldNum(GUPEcoResInstanceAttributeValuesView, RecId));
                        metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeName));
                        metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeTypeName));
                        metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, TextValue));
                        metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, BooleanValue));
                        metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.relations(false);

                        metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.joinMode(JoinMode::OuterJoin);
                        metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.fetchMode(QueryFetchMode::One2One);
                        qbdsName = metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.name();
                    }                        

                    // Have to split data source in case we get a mix of inclusion/exclusion for customer super group and banner group
                    if (attributeLink.AttributeName == METConstants::BannerGroup
                    && !metqbdsGUPEcoResInstanceAttributeValuesBannerGroup)
                    {
                        metqbdsGUPEcoResInstanceAttributeValuesBannerGroup = metqbdsCustomerInstanceValue.addDataSource(tableNum(GUPEcoResInstanceAttributeValuesView));
                        metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.addLink(fieldNum(CustomerInstanceValue, RecId), fieldNum(GUPEcoResInstanceAttributeValuesView, RecId));
                        metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeName));
                        metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeTypeName));
                        metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, TextValue));
                        metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, BooleanValue));
                        metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.relations(false);

                        metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.joinMode(JoinMode::OuterJoin);
                        metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.fetchMode(QueryFetchMode::One2One);
                        qbdsName = metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.name();
                    }

                }
                else
                {
                    continue;  // If there are more attribute from other source, please add more datasource table join the query.
                }

                // If OR condition is already set to ALL, then skip all other OR conditions.
                if (ruleCondition.METisOR == NoYes::Yes && isOrConditionSetToALL)
                {
                    continue;
                }

                // If one Or condition is set with empty value(ALL), that means no matter what is the setting on transaction, all OR conditions are matched.
                if (ruleCondition.METisOR == NoYes::Yes && ruleCondition.ConditionValue == '')
                {
                    isOrConditionSetToALL = true;
                    orQueryRanges = '';
                    continue;
                }

                // Skip the AND condition with empty value.
                if (ruleCondition.METisOR == NoYes::No && ruleCondition.ConditionValue == '')
                {
                    continue;
                }

                // All AND conditions are combined with && in query script
                if (ruleCondition.METisOR == NoYes::No && andQueryRanges)
                {
                    andQueryRanges  += ' && ';
                }

                // All OR conditions are combined with || in query script
                if (ruleCondition.METisOR == NoYes::Yes && orQueryRanges)
                {
                    orQueryRanges  += ' || ';
                }

                str singleQueryRange;

                // If the condition value contains '!', that means it is a NOT EQUAL condition. Translate it to ((X.Y != Value1) && (X.Y!= Value2) && ...)
                // ! Exclusion
                if (strContains(ruleCondition.conditionValue, '!'))
                {
                    // For text data type, need to add double quote for the value in query range.
                    // For int, reference data type, no need to add double quote for the value in query range.
                    // For trueFalse data type, use 1 (in price rule condition, it is 'Yes') for true and 0 for false without double quote.
                    // Need to add logic for trueFalse data type, I didn't cover the case in this exmaple.
                    str queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '%1.%2 != "%3"' : '%1.%2 != %3';

                    // Multiple values comma separated
                    if (strContains(ruleCondition.ConditionValue, ','))
                    {
                        ListEnumerator valuesListEnumerator = strSplit(strReplace(ruleCondition.ConditionValue, '!', ''), ',').getEnumerator();
                        while (valuesListEnumerator.moveNext())
                        {
                            if (singleQueryRange)
                            {
                                singleQueryRange += ' && ';
                            }

                            // for customer attributes, need to add extra condition on the attribute name
                            if (attributeLink.AttributeName == METConstants::CustomerSuperGroup
                            ||  attributeLink.AttributeName == METConstants::BannerGroup)
                            {
                                queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '(%1.%2 != "%3") && (%1.%4 == "%5")' : '(%1.%2 != %3) && (%1.%4 == "%5")';

                                singleQueryRange += strFmt('(' + queryFmt + ')',
                                          qbdsName,
                                          METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink),
                                          valuesListEnumerator.current(),
                                          fieldStr(GUPEcoResInstanceAttributeValuesView, AttributeName),
                                          attributeLink.AttributeName);
                            }
                            else
                            {
                                // MS code
                                singleQueryRange += strFmt('(' + queryFmt + ')', qbdsName, METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink), valuesListEnumerator.current());
                            }
                        }
                    }
                    // Single value
                    else
                    {
                        // for customer attributes, need to add extra condition on the attribute name
                        if (attributeLink.AttributeName == METConstants::CustomerSuperGroup
                        ||  attributeLink.AttributeName == METConstants::BannerGroup)
                        {
                            queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '(%1.%2 != "%3") && (%1.%4 == "%5")' : '(%1.%2 != %3) && (%1.%4 == "%5")';

                            singleQueryRange = strFmt(queryFmt,
                                      qbdsName,
                                      METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink),
                                      strReplace(ruleCondition.ConditionValue, '!', ''),
                                      fieldStr(GUPEcoResInstanceAttributeValuesView, AttributeName),
                                      attributeLink.AttributeName);                          
                        }
                        // MS code
                        else
                        {
                            singleQueryRange = strFmt(queryFmt, qbdsName, METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink), strReplace(ruleCondition.ConditionValue, '!', ''));
                        }
                    }

                }
                // Inclusion
                else  // EQUAL condition . Translate it to ((X.Y == Value1) || (X.Y == Value2) || ...)
                {
                    str queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '%1.%2 == "%3"' : '%1.%2 == %3';

                    // Multiple values comma separated
                    if (strContains(ruleCondition.ConditionValue, ','))
                    {
                        ListEnumerator valuesListEnumerator = strSplit(ruleCondition.ConditionValue, ',').getEnumerator();
                        while (valuesListEnumerator.moveNext())
                        {
                            if (singleQueryRange)
                            {
                                singleQueryRange += ' || ';
                            }

                            // for customer attributes, need to add extra condition on the attribute name
                            if (attributeLink.AttributeName == METConstants::CustomerSuperGroup
                            ||  attributeLink.AttributeName == METConstants::BannerGroup)
                            {
                                queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '(%1.%2 == "%3") && (%1.%4 == "%5")' : '(%1.%2 == %3) && (%1.%4 == "%5")';

                                singleQueryRange += strFmt('(' + queryFmt + ')',
                                      qbdsName,
                                      METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink),
                                      valuesListEnumerator.current(),
                                      fieldStr(GUPEcoResInstanceAttributeValuesView, AttributeName),
                                      attributeLink.AttributeName);    
                            }
                            else
                            {
                                // MS code
                                singleQueryRange += strFmt('(' + queryFmt + ')', qbdsName, METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink), valuesListEnumerator.current());
                            }
                        }
                    }
                    // Single value
                    else
                    {
                        // for customer attributes, need to add extra condition on the attribute name
                        if (attributeLink.AttributeName == METConstants::CustomerSuperGroup
                        ||  attributeLink.AttributeName == METConstants::BannerGroup)
                        {
                            queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '(%1.%2 == "%3") && (%1.%4 == "%5")' : '(%1.%2 == %3) && (%1.%4 == "%5")';

                            singleQueryRange = strFmt(queryFmt,
                                      qbdsName,
                                      METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink),
                                      ruleCondition.ConditionValue,
                                      fieldStr(GUPEcoResInstanceAttributeValuesView, AttributeName),
                                      attributeLink.AttributeName);
                        }
                        else
                        {
                            // MS code
                            singleQueryRange = strFmt(queryFmt, qbdsName, METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink), ruleCondition.ConditionValue);
                        }
                    }
                }

                if (ruleCondition.METisOR == NoYes::No)
                {
                    andQueryRanges += '(' + singleQueryRange + ')';
                }

                if (ruleCondition.METisOR == NoYes::Yes)
                {
                    orQueryRanges += '(' + singleQueryRange + ')';
                }
            }

            // And the end the condition is ((AndAttr1 && AndAttr2 && ...) && (OrAttr1 || OrAttr2 || ...))
            str queryRanges;
            if (andQueryRanges)
            {
                queryRanges += '(' + andQueryRanges + ')' + (orQueryRanges != '' ? (' && ' + '(' + orQueryRanges + ')') : '');
            }
            else
            {
                queryRanges = orQueryRanges;
            }

            if (queryRanges)
            {
                // For debug
                // info("Header Rule Query Ranges: " + queryRanges);
                queryRangesAdded = true;
                qbds.addRange(accountFieldId).value(queryRanges);
            }
        }

        select firstonly RecId from lineRule
            where lineRule.RecId == rebateTable.PricingRuleLine
               && lineRule.PriceAttributeGroupName != ''
            exists join ruleCondition
            where ruleCondition.RuleId == lineRule.RecId
               && ruleCondition.METisOR == NoYes::Yes;

        if (lineRule.RecId)
        {
            QueryBuildDataSource qbds = query.dataSourceTable(this.transTable());
            QueryBuildDataSource qbdsInventTable = query.dataSourceTable(tableNum(InventTable));
            QueryBuildDataSource qbdsInventTableProductAttribute;

            //QueryBuildDataSource metqbdsTAMRebateGroupLink;
            QueryBuildDataSource metqbdsProductInstanceValue;
            QueryBuildDataSource metqbdsGUPEcoResInstanceAttributeValuesBrand, metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel;
            QueryBuildDataSource metqbdsInventDim;
            QueryBuildDataSource metqbdsInventItemOrderSetup;
            QueryBuildDataSource metqbdsReqItemTable;
            QueryBuildDataSource metqbdsEcoResProductCategory;
            QueryBuildDataSource metqbdsEcoResCategory;
            QueryBuildDataSource metqbdsEcoResCategoryHierarchyRole;

            str andQueryRanges, orQueryRanges;
            boolean isOrConditionSetToALL = false;
            FieldId itemFieldId = this.itemFieldId();
            FieldId inventDimIdFieldId = this.inventDimIdFieldId(); // Added

            str value;
            str qbdsName;

            while select ruleCondition
                where ruleCondition.RuleId == lineRule.RecId
                join AttributeName, TypeName, RecId, PriceAttributeClassId, Source, AttributeProviderClassId, SourceName, FieldName, AttributeDataType from attributeLink
                where attributeLink.RecId == ruleCondition.ConditionAttribute
                && ruleCondition.conditionValue
            {
                qbdsName = qbds.name();

                // In this example, I only handle SalesLine and CustTable as attribute source for line rule.
                if (attributeLink.SourceName == METConstants::SalesLine)
                {
                    qbdsName = qbds.name();
                }
                // Item number attribute
                else if (attributeLink.SourceName == METConstants::InventTable)
                {
                    if (!qbdsInventTable)
                    {
                        qbdsInventTable = qbds.addDataSource(tableNum(InventTable));
                        qbdsInventTable.addLink(itemFieldId, fieldNum(InventTable, ItemId));
                        qbdsInventTable.addSelectionField(fieldNum(InventTable, ItemId));
                        qbdsInventTable.relations(false);
                        qbdsInventTable.joinMode(JoinMode::InnerJoin);
                        qbdsInventTable.fetchMode(QueryFetchMode::One2One);
                    }

                    qbdsName = qbdsInventTable.name();
                }
                // Rebate management group (not used)
                /*else if (attributeLink.SourceName == 'TAMRebateGroupLink')
                {
                    if (!qbdsInventTableTAMRebateGroupLink)
                    {
                        qbdsInventTableTAMRebateGroupLink = qbds.addDataSource(tableNum(InventTable));
                        qbdsInventTableTAMRebateGroupLink.addLink(itemFieldId, fieldNum(InventTable, ItemId));
                        qbdsInventTableTAMRebateGroupLink.addSelectionField(fieldNum(InventTable, ItemId));
                        qbdsInventTableTAMRebateGroupLink.relations(false);
                        qbdsInventTableTAMRebateGroupLink.joinMode(JoinMode::InnerJoin);
                        qbdsInventTableTAMRebateGroupLink.fetchMode(QueryFetchMode::One2One);
                    }

                    if (!metqbdsTAMRebateGroupLink)
                    {
                        metqbdsTAMRebateGroupLink = qbdsInventTableTAMRebateGroupLink.addDataSource(tableNum(TAMRebateGroupLink));
                        metqbdsTAMRebateGroupLink.addLink(fieldNum(InventTable, TableId), fieldNum(TAMRebateGroupLink, RefTableId));
                        metqbdsTAMRebateGroupLink.addLink(fieldNum(InventTable, RecId), fieldNum(TAMRebateGroupLink, RefRecId));
                        metqbdsTAMRebateGroupLink.addSelectionField(fieldNum(TAMRebateGroupLink, RebateGroupId));
                        metqbdsTAMRebateGroupLink.relations(false);
                        metqbdsTAMRebateGroupLink.joinMode(JoinMode::OuterJoin);
                        metqbdsTAMRebateGroupLink.fetchMode(QueryFetchMode::One2One);
                    }

                    qbdsName = metqbdsTAMRebateGroupLink.name();
                }*/
                // Brand and private label product attributes
                else if (attributeLink.SourceName == METConstants::GUPPricingAttributeProviderEcoResProductAttribute)
                {
                    if (!qbdsInventTableProductAttribute)
                    {
                        qbdsInventTableProductAttribute = qbds.addDataSource(tableNum(InventTable));
                        qbdsInventTableProductAttribute.addLink(itemFieldId, fieldNum(InventTable, ItemId));
                        qbdsInventTableProductAttribute.addSelectionField(fieldNum(InventTable, ItemId));
                        qbdsInventTableProductAttribute.relations(false);
                        qbdsInventTableProductAttribute.joinMode(JoinMode::InnerJoin);
                        qbdsInventTableProductAttribute.fetchMode(QueryFetchMode::One2One);
                    }

                    if (!metqbdsProductInstanceValue)
                    {
                        metqbdsProductInstanceValue = qbdsInventTableProductAttribute.addDataSource(tableNum(EcoResProductInstanceValue));
                        metqbdsProductInstanceValue.addLink(fieldNum(InventTable, Product), fieldNum(EcoResProductInstanceValue, Product));
                        metqbdsProductInstanceValue.addSelectionField(fieldNum(EcoResProductInstanceValue, RecId));
                        metqbdsProductInstanceValue.relations(false);
                        metqbdsProductInstanceValue.joinMode(JoinMode::InnerJoin);
                        metqbdsProductInstanceValue.fetchMode(QueryFetchMode::One2One);
                    }

                    if (attributeLink.AttributeName == METConstants::Brand
                    && !metqbdsGUPEcoResInstanceAttributeValuesBrand)
                    {
                        metqbdsGUPEcoResInstanceAttributeValuesBrand = metqbdsProductInstanceValue.addDataSource(tableNum(GUPEcoResInstanceAttributeValuesView));
                        metqbdsGUPEcoResInstanceAttributeValuesBrand.addLink(fieldNum(EcoResProductInstanceValue, RecId), fieldNum(GUPEcoResInstanceAttributeValuesView, RecId));
                        metqbdsGUPEcoResInstanceAttributeValuesBrand.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeName));
                        metqbdsGUPEcoResInstanceAttributeValuesBrand.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeTypeName));
                        metqbdsGUPEcoResInstanceAttributeValuesBrand.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, TextValue));
                        metqbdsGUPEcoResInstanceAttributeValuesBrand.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, BooleanValue));
                        metqbdsGUPEcoResInstanceAttributeValuesBrand.relations(false);

                        metqbdsGUPEcoResInstanceAttributeValuesBrand.joinMode(JoinMode::OuterJoin);
                        metqbdsGUPEcoResInstanceAttributeValuesBrand.fetchMode(QueryFetchMode::One2One);
                        qbdsName = metqbdsGUPEcoResInstanceAttributeValuesBrand.name();
                    }

                    // Have to split data source in case we get a mix of inclusion/exclusion for brand and private label
                    if (attributeLink.AttributeName == METConstants::PrivateLabel
                    && !metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel)
                    {
                        metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel = metqbdsProductInstanceValue.addDataSource(tableNum(GUPEcoResInstanceAttributeValuesView));
                        metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel.addLink(fieldNum(EcoResProductInstanceValue, RecId), fieldNum(GUPEcoResInstanceAttributeValuesView, RecId));
                        metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeName));
                        metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeTypeName));
                        metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, TextValue));
                        metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, BooleanValue));
                        metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel.relations(false);

                        metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel.joinMode(JoinMode::OuterJoin);
                        metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel.fetchMode(QueryFetchMode::One2One);
                        qbdsName = metqbdsGUPEcoResInstanceAttributeValuesPrivateLabel.name();
                    }

                }
                // Default order settings: Metcash item type, Metcash legacy code (MLC), item subrange
                else if (attributeLink.SourceName == METConstants::METInventItemOrderSetup)
                {
                    // SalesLine -> InventDim -> METInventItemOrderSetup
                    if (!metqbdsInventDim)
                    {
                        metqbdsInventDim = qbds.addDataSource(tableNum(InventDim));
                        metqbdsInventDim.addLink(fieldNum(SalesLine, InventDimId), fieldNum(InventDim, InventDimId));
                        metqbdsInventDim.addSelectionField(fieldNum(InventDim, InventSiteId));
                        metqbdsInventDim.addSelectionField(fieldNum(InventDim, InventLocationId));
                        metqbdsInventDim.relations(false);
                        metqbdsInventDim.joinMode(JoinMode::InnerJoin);
                        metqbdsInventDim.fetchMode(QueryFetchMode::One2One);
                    }

                    if (!metqbdsInventItemOrderSetup)
                    {
                        metqbdsInventItemOrderSetup = metqbdsInventDim.addDataSource(tableNum(METInventItemOrderSetup));
                        metqbdsInventItemOrderSetup.addLink(fieldNum(InventDim, InventSiteId), fieldNum(METInventItemOrderSetup, SiteId));
                        metqbdsInventItemOrderSetup.addSelectionField(fieldNum(METInventItemOrderSetup, ItemType));
                        metqbdsInventItemOrderSetup.addSelectionField(fieldNum(METInventItemOrderSetup, MTCLegacyCode));
                        metqbdsInventItemOrderSetup.addSelectionField(fieldNum(METInventItemOrderSetup, SubrangeId));
                        metqbdsInventItemOrderSetup.relations(false);
                        metqbdsInventItemOrderSetup.joinMode(JoinMode::OuterJoin);
                        metqbdsInventItemOrderSetup.fetchMode(QueryFetchMode::One2One);

                        str queryFmt = '(%1.%2 == %3.%2)';
                        str range = strFmt(queryFmt, qbds.name(), fieldStr(SalesLine, ItemId), metqbdsInventItemOrderSetup.name());

                        metqbdsInventItemOrderSetup.addRange(fieldNum(METInventItemOrderSetup, ItemId)).value(range);

                    }

                    qbdsName = metqbdsInventItemOrderSetup.name();
                }
                // Item coverage > vendor account
                else if (attributeLink.SourceName == METConstants::ReqItemTable)
                {
                    // SalesLine -> InventDim -> ReqItemTable
                    if (!metqbdsInventDim)
                    {
                        metqbdsInventDim = qbds.addDataSource(tableNum(InventDim));
                        metqbdsInventDim.addLink(inventDimIdFieldId, fieldNum(InventDim, InventDimId));
                        metqbdsInventDim.addSelectionField(fieldNum(InventDim, InventSiteId));
                        metqbdsInventDim.addSelectionField(fieldNum(InventDim, InventLocationId));
                        metqbdsInventDim.relations(false);
                        metqbdsInventDim.joinMode(JoinMode::InnerJoin);
                        metqbdsInventDim.fetchMode(QueryFetchMode::One2One);
                    }

                    if (!metqbdsReqItemTable)
                    {
                        metqbdsReqItemTable = qbds.addDataSource(tableNum(ReqItemTable));
                        metqbdsReqItemTable.addLink(itemFieldId, fieldNum(ReqItemTable, ItemId));
                        metqbdsReqItemTable.addSelectionField(fieldNum(ReqItemTable, VendId));
                        metqbdsReqItemTable.addSelectionField(fieldNum(ReqItemTable, CovInventDimId));
                        metqbdsReqItemTable.relations(false);

                        metqbdsReqItemTable.joinMode(JoinMode::OuterJoin);
                        metqbdsReqItemTable.fetchMode(QueryFetchMode::One2One);

                        QueryBuildDataSource metqbdsCovInventDim;
                        metqbdsCovInventDim = metqbdsReqItemTable.addDataSource(tableNum(InventDim));
                        metqbdsCovInventDim.addLink(fieldNum(ReqItemTable, CovInventDimId), fieldNum(InventDim, InventDimId));
                        metqbdsCovInventDim.addSelectionField(fieldNum(InventDim, InventSiteId));
                        metqbdsCovInventDim.addSelectionField(fieldNum(InventDim, InventLocationId));
                        metqbdsCovInventDim.relations(false);
                        metqbdsCovInventDim.joinMode(JoinMode::ExistsJoin);
                        metqbdsCovInventDim.fetchMode(QueryFetchMode::One2One);

                        // Add CovInventDim and match it with the salesLine site and WH
                        str queryFmt = '((%1.%2 == %3.%2) && (%1.%4 == %3.%4))';
                        str range = strFmt(queryFmt, metqbdsInventDim.name(), fieldStr(InventDim, InventSiteId), metqbdsCovInventDim.name(), fieldStr(InventDim, InventLocationId));

                        metqbdsCovInventDim.addRange(fieldNum(InventDim, InventSiteId)).value(range);
                    }

                    qbdsName = metqbdsReqItemTable.name();
                }
                // Product category : MET Category (level 5), Commmodity (level 6), SubCommodity (level 7)
                else if (attributeLink.SourceName == METConstants::EcoResProductCategory)
                {
                    if (!qbdsInventTable)
                    {
                        qbdsInventTable = qbds.addDataSource(tableNum(InventTable));
                        qbdsInventTable.addLink(itemFieldId, fieldNum(InventTable, ItemId));
                        qbdsInventTable.addSelectionField(fieldNum(InventTable, ItemId));
                        qbdsInventTable.relations(false);
                        qbdsInventTable.joinMode(JoinMode::InnerJoin);
                        qbdsInventTable.fetchMode(QueryFetchMode::One2One);
                    }

                    if (!metqbdsEcoResProductCategory)
                    {
                        metqbdsEcoResProductCategory = qbdsInventTable.addDataSource(tableNum(EcoResProductCategory));
                        metqbdsEcoResProductCategory.addLink(fieldNum(InventTable, Product), fieldNum(EcoResProductCategory, Product));
                        metqbdsEcoResProductCategory.joinMode(JoinMode::InnerJoin);

                        metqbdsEcoResCategory = metqbdsEcoResProductCategory.addDataSource(tableNum(EcoResCategory));
                        metqbdsEcoResCategory.addLink(fieldNum(EcoResProductCategory, Category), fieldNum(EcoResCategory, RecId));
                        metqbdsEcoResCategory.joinMode(JoinMode::InnerJoin);

                        metqbdsEcoResCategoryHierarchyRole = metqbdsEcoResCategory.addDataSource(tableNum(EcoResCategoryHierarchyRole));
                        metqbdsEcoResCategoryHierarchyRole.addLink(fieldNum(EcoResCategory, CategoryHierarchy), fieldNum(EcoResCategoryHierarchyRole, CategoryHierarchy));
                        metqbdsEcoResCategoryHierarchyRole.joinMode(JoinMode::ExistsJoin);
                    }
                }
                else
                {
                    continue;
                }

                if (ruleCondition.METisOR == NoYes::Yes && isOrConditionSetToALL)
                {
                    continue;
                }

                if (ruleCondition.METisOR == NoYes::Yes && ruleCondition.ConditionValue == '')
                {
                    isOrConditionSetToALL = true;
                    orQueryRanges = '';
                    continue;
                }

                if (ruleCondition.METisOR == NoYes::No && ruleCondition.ConditionValue == '')
                {
                    continue;
                }

                if (ruleCondition.METisOR == NoYes::No && andQueryRanges)
                {
                    andQueryRanges  += ' && ';
                }

                if (ruleCondition.METisOR == NoYes::Yes && orQueryRanges)
                {
                    orQueryRanges  += ' || ';
                }

                str singleQueryRange;

                // Added product category
                if (attributeLink.AttributeName == METConstants::METCategory
                ||  attributeLink.AttributeName == METConstants::Commodity
                ||  attributeLink.AttributeName == METConstants::Subcommodity)
                {
                    str queryRanges = this.metConstructCategoryRanges(ruleCondition.ConditionValue, metqbdsEcoResCategory);

                    if (queryRanges)
                    {
                        singleQueryRange = queryRanges;
                    }
                }
                else
                {
                    // ! Exclusion
                    if (strContains(ruleCondition.conditionValue, '!'))
                    {                        
                        // MS code
                        str queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '%1.%2 != "%3"' : '%1.%2 != %3';                          

                        // Multiple values comma separated
                        if (strContains(ruleCondition.ConditionValue, ','))
                        {
                            ListEnumerator valuesListEnumerator = strSplit(strReplace(ruleCondition.ConditionValue, '!', ''), ',').getEnumerator();
                            while (valuesListEnumerator.moveNext())
                            {
                                if (singleQueryRange)
                                {
                                    singleQueryRange += ' && ';
                                }

                                // for product attributes, need to add extra condition on the attribute name
                                if (attributeLink.AttributeName == METConstants::Brand
                                ||  attributeLink.AttributeName == METConstants::PrivateLabel)
                                {
                                    queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '(%1.%2 != "%3") && (%1.%4 == "%5")' : '(%1.%2 != %3) && (%1.%4 == "%5")';

                                    value = valuesListEnumerator.current();

                                    // ConditionValue is saved as a string 'Yes'/'No' for boolean attribute 'Private label'
                                    // Need to convert it to 1/0 for the query range
                                    if (attributeLink.AttributeName == METConstants::PrivateLabel)
                                    {
                                        value = ruleCondition.ConditionValue == 'Yes' ? '1' : '0';
                                    }

                                    singleQueryRange += strFmt('(' + queryFmt + ')',
                                                    qbdsName,
                                                    METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink),
                                                    value,
                                                    fieldStr(GUPEcoResInstanceAttributeValuesView, AttributeName),
                                                    attributeLink.AttributeName);
                                }
                                // MS code
                                else
                                {
                                    singleQueryRange += strFmt('(' + queryFmt + ')', qbdsName, METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink), valuesListEnumerator.current());
                                }
                            }
                        }
                        // Single value
                        else
                        {
                            // for product attributes, need to add extra condition on the attribute name
                            if (attributeLink.AttributeName == METConstants::Brand
                            ||  attributeLink.AttributeName == METConstants::PrivateLabel)
                            {
                                queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '(%1.%2 != "%3") && (%1.%4 == "%5")' : '(%1.%2 != %3) && (%1.%4 == "%5")';

                                value = strReplace(ruleCondition.ConditionValue, '!', '');

                                // ConditionValue is saved as a string 'Yes'/'No' for boolean attribute 'Private label'
                                // Need to convert it to 1/0 for the query range
                                if (attributeLink.AttributeName == METConstants::PrivateLabel)
                                {
                                    value = ruleCondition.ConditionValue == 'Yes' ? '1' : '0';
                                }

                                singleQueryRange = strFmt(queryFmt,
                                                    qbdsName,
                                                    METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink),
                                                    value,
                                                    fieldStr(GUPEcoResInstanceAttributeValuesView, AttributeName),
                                                    attributeLink.AttributeName);
                            }
                            //MS code
                            else
                            {
                                singleQueryRange = strFmt(queryFmt, qbdsName, METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink), strReplace(ruleCondition.ConditionValue, '!', ''));
                            }
                        }
                    }
                    // Inclusion
                    else
                    {                            
                        // MS code
                        str queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '%1.%2 == "%3"' : '%1.%2 == %3';

                        // Multiple values comma separated
                        if (strContains(ruleCondition.ConditionValue, ','))
                        {
                            ListEnumerator valuesListEnumerator = strSplit(ruleCondition.ConditionValue, ',').getEnumerator();
                            while (valuesListEnumerator.moveNext())
                            {
                                if (singleQueryRange)
                                {
                                    singleQueryRange += ' || ';
                                }

                                // for product attributes, need to add extra condition on the attribute name
                                if (attributeLink.AttributeName == METConstants::Brand
                                ||  attributeLink.AttributeName == METConstants::PrivateLabel)
                                {
                                    queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '(%1.%2 == "%3") && (%1.%4 == "%5")' : '(%1.%2 == %3) && (%1.%4 == "%5")';

                                    value = valuesListEnumerator.current();

                                    // ConditionValue is saved as a string 'Yes'/'No' for boolean attribute 'Private label'
                                    // Need to convert it to 1/0 for the query range
                                    if (attributeLink.AttributeName == METConstants::PrivateLabel)
                                    {
                                        value = valuesListEnumerator.current() == 'Yes' ? '1' : '0';
                                    }

                                    singleQueryRange += strFmt('(' + queryFmt + ')',
                                                                qbdsName,
                                                                METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink), //field,
                                                                value,
                                                                fieldStr(GUPEcoResInstanceAttributeValuesView, AttributeName),
                                                                attributeLink.AttributeName);
                                }
                                else
                                {
                                    // MS code
                                    singleQueryRange += strFmt('(' + queryFmt + ')', qbdsName, METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink), valuesListEnumerator.current());
                                }

                            }
                        }
                        // Single value
                        else
                        {
                            // for product attributes, need to add extra condition on the attribute name
                            if (attributeLink.AttributeName == METConstants::Brand
                            ||  attributeLink.AttributeName == METConstants::PrivateLabel)
                            {
                                queryFmt = attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '(%1.%2 == "%3") && (%1.%4 == "%5")' : '(%1.%2 == %3) && (%1.%4 == "%5")';

                                value = ruleCondition.ConditionValue;

                                // ConditionValue is saved as a string 'Yes'/'No' for boolean attribute 'Private label'
                                // Need to convert it to 1/0 for the query range
                                if (attributeLink.AttributeName == METConstants::PrivateLabel)
                                {
                                    value = ruleCondition.ConditionValue == 'Yes' ? '1' : '0';
                                }


                                singleQueryRange = strFmt(queryFmt,
                                                    qbdsName,
                                                    METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink),
                                                    value,
                                                    fieldStr(GUPEcoResInstanceAttributeValuesView, AttributeName),
                                                    attributeLink.AttributeName);   
                            }
                            else
                            {
                                // MS code
                                singleQueryRange = strFmt(queryFmt, qbdsName, METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(attributeLink), ruleCondition.ConditionValue);
                            }
                        }                            
                    }
                }

                if (ruleCondition.METisOR == NoYes::No)
                {
                    andQueryRanges += '(' + singleQueryRange + ')';
                }

                if (ruleCondition.METisOR == NoYes::Yes)
                {
                    orQueryRanges += '(' + singleQueryRange + ')';
                }
            }

            str queryRanges;
            if (andQueryRanges)
            {
                queryRanges += '(' + andQueryRanges + ')' + (orQueryRanges != '' ? (' && ' + '(' + orQueryRanges + ')') : '');
            }
            else
            {
                queryRanges = orQueryRanges;
            }

            if (queryRanges)
            {
                // For dubug
                // info("Line Rule Query Ranges: " + queryRanges);
                queryRangesAdded = true;
                qbds.addRange(itemFieldId).value(queryRanges);
            }
        }

        // If there is at least one OR and queryRanges added to the query
        // need to add the group by to handle the one 2 many join for product/customer attributes
        if (queryRangesAdded)
        {
            this.metAddOrAttributesGroupBy();
        }
    }

    return query;
}

/// <summary>
/// Bug 306156: [MS] CB201 - Customer rebates: Attribute Filtering Logic Not Correct - MS SR # 2410100030001214
/// VNG copied from GUPPricingAttributeEcoResProductCategoryCategory
/// </summary>
/// <param name = "_value">anytype</param>
/// <param name = "_qbdsEcoResCategory">QueryBuildDataSource</param>
/// <returns>str</returns>
private str metConstructCategoryRanges(anytype _value, QueryBuildDataSource _qbdsEcoResCategory)
{
    System.String valueStr, exclusionSign = '!';
    str queryRanges;
    boolean isExclusionOpt;

    str qbdsName = _qbdsEcoResCategory.name(); // added

    List recIdList = strSplit(_value, ',');
    ListEnumerator enumerator = recIdList.getEnumerator();
    while (enumerator.moveNext())
    {
        valueStr = enumerator.current();
        isExclusionOpt = false;
        if (valueStr.StartsWith(exclusionSign))
        {
            valueStr = valueStr.Substring(1);
            isExclusionOpt = true;
        }

        int64 value = any2Int64(valueStr);
        EcoResCategory ecoResCategory = EcoResCategory::find(value);
        if (ecoResCategory)
        {
            if (queryRanges)
            {
                queryRanges += isExclusionOpt ? ' && ' : ' || ';
            }

            if (isExclusionOpt)
            {
                // (((NestedSetRight < ecoResCategory.NestedSetLeft) || (NestedSetLeft > ecoResCategory.NestedSetRight)) && (CategoryHierarchy == ecoResCategory.CategoryHierarchy))
                queryRanges += strFmt('(((%1.%2 < %3) || (%1.%4 > %5)) && (%1.%6 == %7))',
                                      qbdsName,
                                      fieldStr(EcoResCategory, NestedSetRight),
                                      any2Str(ecoResCategory.NestedSetLeft),
                                      fieldStr(EcoResCategory, NestedSetLeft),
                                      any2Str(ecoResCategory.NestedSetRight),
                                      fieldStr(EcoResCategory, CategoryHierarchy),
                                      int642Str(ecoResCategory.CategoryHierarchy));
            }
            else
            {
                // (((NestedSetLeft >= ecoResCategory.NestedSetLeft) && (NestedSetRight <= ecoResCategory.NestedSetRight)) && (CategoryHierarchy == ecoResCategory.CategoryHierarchy))
                queryRanges += strFmt('(((%1.%2 >= %3) && (%1.%4 <= %5)) && (%1.%6 == %7))',
                                      qbdsName,
                                      fieldStr(EcoResCategory, NestedSetLeft),
                                      any2Str(ecoResCategory.NestedSetLeft),
                                      fieldStr(EcoResCategory, NestedSetRight),
                                      any2Str(ecoResCategory.NestedSetRight),
                                      fieldStr(EcoResCategory, CategoryHierarchy),
                                      int642Str(ecoResCategory.CategoryHierarchy));
            }
        }
    }

    return queryRanges;
}

/// <summary>
/// Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
/// Copied the private method to add inventory dimension data source if it doesn't exist
/// </summary>
protected void metAddInventDimDS()
{
    // could be already added by standard code if users configured the inventory dimension criteria against TAMRebateTable
    QueryBuildDataSource qdbsInventDim = query.dataSourceTable(tableNum(InventDim));

    if (!qdbsInventDim)
    {      
        QueryBuildDataSource qbds = query.dataSourceTable(this.transTable()).addDataSource(tableNum(InventDim));

        qbds.relations(true);
        qbds.joinMode(JoinMode::ExistsJoin);
        qbds.fetchMode(QueryFetchMode::One2One);
    }

    //inventDimParm.queryAddRange(qbds, inventDimCriteria);
}

/// <summary>
/// Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
/// Add the default order settings data source
/// </summary>
protected void metAddInventItemOrderSetupDS()
{        
    QueryBuildDataSource qbds = query.dataSourceTable(tableNum(InventDim)).addDataSource(tableNum(METInventItemOrderSetup));

    /*qbds.addLink(this.itemFieldId(), fieldNum(METInventItemOrderSetup, ItemId));*/
    qbds.addLink(fieldNum(InventDim, InventSiteId), fieldNum(METInventItemOrderSetup, SiteId));

    qbds.joinMode(JoinMode::ExistsJoin);
    qbds.fetchMode(QueryFetchMode::One2One);

    QueryBuildRange qbrItemId = SysQuery::findOrCreateRange(qbds, fieldNum(METInventItemOrderSetup, ItemId));

    QueryBuildDataSource qbdsTransTable = query.dataSourceTable(this.transTable());

    const str itemIdRange = '(%1.ITEMID == %2.ITEMID)';

    qbrItemId.value(strFmt(itemIdRange, qbdsTransTable.name(), qbds.name()));
    //inventDimParm.queryAddRange(qbds, inventDimCriteria);
}

/// <summary>
/// Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
/// Filter transactions by the item distribution method
/// </summary>
void metAddItemDistributionMethodRange()
{
    TAMRebateDeal rebateDeal = rebateTable.TAMRebateDeal();

    // Only for customer rebates or vendor rebates based on sales
    // and when item distribution method is selected
    if ((rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Cust
    || (rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend
    && rebateTable.RebateBasisVend == TAMRebateBasisVend::Sales))
    && rebateTable.METItemDistributionMethod)
    {
        // Add invent dimension ds
        this.metAddInventDimDS();

        // Add default order settings ds
        this.metAddInventItemOrderSetupDS();

        QueryBuildRange qbr = SysQuery::findOrCreateRange(query.dataSourceTable(tableNum(METInventItemOrderSetup)), fieldNum(METInventItemOrderSetup, DistributionMethod));

        switch (rebateTable.METItemDistributionMethod)
        {
            case METItemDistributionMethod::Warehouse:
                qbr.value(queryValue("W"));
                break;
            case METItemDistributionMethod::ChargeThrough:
                qbr.value(queryValue("H"));
                break;

            default:
                // Do nothing, no filter
                break;
        }
    }
}

/// <summary>
/// Bug 306156: [MS] CB201 - Customer rebates: Attribute Filtering Logic Not Correct - MS SR # 2410100030001214
/// Group by for OR attribute filtering to eliminate duplicates with product/customer attributes e.g. product = item1 OR brand = brand1
/// </summary>
private void metAddOrAttributesGroupBy()
{
    QueryBuildDataSource qbdsHeader = query.dataSourceTable(this.journalTable());

    // GROUP BY
    if (qbdsHeader.table() == tableNum(SalesTable))
    {
        qbdsHeader.orderMode(OrderMode::GroupBy);
        qbdsHeader.addGroupByField(fieldNum(SalesTable, InvoiceAccount));
        qbdsHeader.addGroupByField(fieldNum(SalesTable, CashDisc));
        qbdsHeader.addGroupByField(fieldNum(SalesTable, DataAreaId));
        qbdsHeader.addGroupByField(fieldNum(SalesTable, InclTax));
    }
    else if (qbdsHeader.table() == tableNum(CustPackingSlipJour))
    {
        qbdsHeader.orderMode(OrderMode::GroupBy);
        qbdsHeader.addGroupByField(fieldNum(CustPackingSlipJour, InvoiceAccount));
    }
    else if (qbdsHeader.table() == tableNum(CustInvoiceJour))
    {
        qbdsHeader.orderMode(OrderMode::GroupBy);
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, InvoiceAccount));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, CashDiscCode));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, SalesId));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, CurrencyCode));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, InvoiceId));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, InvoiceDate));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, LedgerVoucher));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, RefNum));
        qbdsHeader.addGroupByField(fieldNum(CustInvoiceJour, DocumentNum));
    }

    QueryBuildDataSource qbdsLine = query.dataSourceTable(this.transTable());
    // Add group by SalesLine
    if (qbdsLine.table() == tableNum(SalesLine))
    {
        qbdsLine.orderMode(OrderMode::GroupBy);
        qbdsLine.addGroupByField(fieldNum(SalesLine, CreatedDateTime));
        qbdsLine.addGroupByField(fieldNum(SalesLine, InventTransId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, ItemId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, InventDimId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, RecId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, TaxGroup));
        qbdsLine.addGroupByField(fieldNum(SalesLine, TaxItemGroup));
        qbdsLine.addGroupByField(fieldNum(SalesLine, InventTransIdReturn));
        qbdsLine.addGroupByField(fieldNum(SalesLine, SalesId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, CurrencyCode));
        qbdsLine.addGroupByField(fieldNum(SalesLine, PdsCWQty));
        qbdsLine.addGroupByField(fieldNum(SalesLine, SalesQty));
        qbdsLine.addGroupByField(fieldNum(SalesLine, DefaultDimension));
        qbdsLine.addGroupByField(fieldNum(SalesLine, SalesUnit));
        qbdsLine.addGroupByField(fieldNum(SalesLine, TAMRebateExcludeRebateManagement));
        qbdsLine.addGroupByField(fieldNum(SalesLine, LineAmount));
        qbdsLine.addGroupByField(fieldNum(SalesLine, RetailVariantId));
        qbdsLine.addGroupByField(fieldNum(SalesLine, TAMRebateTransId));

        // all fields from SalesPurchLine
        qbdsLine.addGroupByField(fieldNum(SalesLine, SalesPrice));
        qbdsLine.addGroupByField(fieldNum(SalesLine, PriceUnit));
        qbdsLine.addGroupByField(fieldNum(SalesLine, SalesMarkup));

    }
    else if (qbdsLine.table() == tableNum(CustPackingSlipTrans))
    {
        qbdsLine.orderMode(OrderMode::GroupBy);
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, CreatedDateTime));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, InventTransId));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, ItemId));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, InventDimId));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, RecId));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, PackingSlipId));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, CurrencyCode));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, PdsCWQty));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, Qty));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, DefaultDimension));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, SalesUnit));

        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, PriceUnit));
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, DeliveryDate));
        // Very important for Attribute matching in GUPRebateMatchingHelper\checkIfPricingAttributesAreMatched to retrieve the salesTable record
        qbdsLine.addGroupByField(fieldNum(CustPackingSlipTrans, SalesId));
    }
    else if (qbdsLine.table() == tableNum(CustInvoiceTrans))
    {
        qbdsLine.orderMode(OrderMode::GroupBy);
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, CreatedDateTime));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, InventTransId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, ItemId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, InventDimId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, RecId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, TaxGroup));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, TaxItemGroup));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, CurrencyCode));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, PdsCWQty));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, Qty));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, InventQty));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, DefaultDimension));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, SalesUnit));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, LineAmount));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, SumLineDisc));

        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, PriceUnit));

        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, ParentRecId));
        // Very important for Attribute matching in GUPRebateMatchingHelper\checkIfPricingAttributesAreMatched to retrieve the salesTable record
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, SalesId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, InvoiceId));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, InvoiceDate));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, NumberSequenceGroup));
        qbdsLine.addGroupByField(fieldNum(CustInvoiceTrans, DataAreaId));
    }
}
